package br.com.admeclesial.interfaces.rest.matrimonio; import br.com.admeclesial.application.matrimonio.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/celebracoes-matrimoniais") public class CelebracaoMatrimonialRestController { final CelebracaoMatrimonialApplicationService s; public CelebracaoMatrimonialRestController(CelebracaoMatrimonialApplicationService s){this.s=s;} @PostMapping public ResponseEntity<CelebracaoMatrimonialResponse> salvar(@Valid @RequestBody CelebracaoMatrimonialRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @GetMapping("/{uuid}") public CelebracaoMatrimonialResponse buscar(@PathVariable UUID uuid){return s.buscar(uuid);} @GetMapping("/por-processo/{uuid}") public CelebracaoMatrimonialResponse porProcesso(@PathVariable UUID uuid){return s.porProcesso(uuid);} }